1	use crate::services::semantic::Semantic;
2	use biome_analyze::{Rule, RuleDiagnostic, RuleSource, context::RuleContext, declare_lint_rule};
3	use biome_console::markup;
4	use biome_js_semantic::SemanticModel;
5	use biome_js_syntax::{
6	    AnyJsExpression, AnyJsLiteralExpression, JsCallExpression, JsComputedMemberExpression,
7	    JsStaticMemberExpression, global_identifier,
8	};
9	use biome_rowan::AstNode;
10	use biome_rule_options::no_alert::NoAlertOptions;
11	
12	const FORBIDDEN_FUNCTIONS: &[&str] = &["alert", "confirm", "prompt"];
13	const GLOBAL_OBJECTS: &[&str] = &["window", "globalThis"];
14	
15	declare_lint_rule! {
16	    /// Disallow the use of `alert`, `confirm`, and `prompt`.
17	    ///
18	    /// JavaScript's `alert`, `confirm`, and `prompt` functions are widely considered to be obtrusive
19	    /// as UI elements and should be replaced by a more appropriate custom UI implementation.
20	    /// Furthermore, `alert` is often used while debugging code, which should be removed before
21	    /// deployment to production.
22	    ///
23	    /// ## Examples
24	    ///
25	    /// ### Invalid
26	    ///
27	    /// ```js,expect_diagnostic
28	    /// alert("here!");
29	    /// ```
30	    ///
31	    /// ```js,expect_diagnostic
32	    /// confirm("Are you sure?");
33	    /// ```
34	    ///
35	    /// ```js,expect_diagnostic
36	    /// prompt("What's your name?", "John Doe");
37	    /// ```
38	    ///
39	    /// ### Valid
40	    ///
41	    /// ```js
42	    /// customAlert("Something happened!");
43	    /// ```
44	    ///
45	    /// ```js
46	    /// customConfirm("Are you sure?");
47	    /// ```
48	    ///
49	    /// ```js
50	    /// customPrompt("Who are you?");
51	    /// ```
52	    ///
53	    /// ```js
54	    /// function foo() {
55	    ///     const alert = myCustomLib.customAlert;
56	    ///     alert();
57	    /// }
58	    /// ```
59	    pub NoAlert {
60	        version: "2.1.0",
61	        name: "noAlert",
62	        language: "js",
63	        sources: &[RuleSource::Eslint("no-alert").same()],
64	        recommended: false,
65	    }
66	}
67	
68	impl Rule for NoAlert {
69	    type Query = Semantic<JsCallExpression>;
70	    type State = String;
71	    type Signals = Option<Self::State>;
72	    type Options = NoAlertOptions;
73	
74	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
75	        let call = ctx.query();
76	        let model = ctx.model();
77	        let callee = call.callee().ok()?;
78	
79	        check_expression(&callee, model)
80	    }
81	
82	    fn diagnostic(ctx: &RuleContext<Self>, function_name: &Self::State) -> Option<RuleDiagnostic> {
83	        let call = ctx.query();
84	
85	        Some(
86	            RuleDiagnostic::new(
87	                rule_category!(),
88	                call.range(),
89	                markup! {
90	                    "Unexpected "<Emphasis>{function_name}</Emphasis>
91	                },
92	            )
93	            .note(markup! {
94	                "The "<Emphasis>{function_name}</Emphasis>" function is considered to be obtrusive. Replace it with a custom UI implementation."
95	            }),
96	        )
97	    }
98	}
99	
100	fn check_expression(expr: &AnyJsExpression, model: &SemanticModel) -> Option<String> {
101	    match expr {
102	        AnyJsExpression::JsIdentifierExpression(_) => check_global_identifier(expr, model),
103	        AnyJsExpression::JsStaticMemberExpression(member_expr) => {
104	            check_static_member_expression(member_expr, model)
105	        }
106	        AnyJsExpression::JsComputedMemberExpression(computed_member_expr) => {
107	            check_computed_member_expression(computed_member_expr, model)
108	        }
109	        AnyJsExpression::JsParenthesizedExpression(paren_expr) => {
110	            let inner_expr = paren_expr.expression().ok()?;
111	            check_expression(&inner_expr, model)
112	        }
113	        _ => None,
114	    }
115	}
116	
117	fn check_global_identifier(expr: &AnyJsExpression, model: &SemanticModel) -> Option<String> {
118	    let (reference, name) = global_identifier(expr)?;
119	    let name_text = name.text();
120	
121	    if is_forbidden_function(name_text) && model.binding(&reference).is_none() {
122	        Some(name_text.to_string())
123	    } else {
124	        None
125	    }
126	}
127	
128	fn check_static_member_expression(
129	    member_expr: &JsStaticMemberExpression,
130	    model: &SemanticModel,
131	) -> Option<String> {
132	    let object = member_expr.object().ok()?;
133	    let (reference, object_name) = global_identifier(&object)?;
134	    let object_name_text = object_name.text();
135	
136	    if is_global_object(object_name_text) && model.binding(&reference).is_none() {
137	        let member_name = member_expr.member().ok()?;
138	        let member_token = member_name.value_token().ok()?;
139	        let member_name_text = member_token.text_trimmed();
140	
141	        if is_forbidden_function(member_name_text) {
142	            Some(member_name_text.to_string())
143	        } else {
144	            None
145	        }
146	    } else {
147	        None
148	    }
149	}
150	
151	fn check_computed_member_expression(
152	    computed_member_expr: &JsComputedMemberExpression,
153	    model: &SemanticModel,
154	) -> Option<String> {
155	    let object = computed_member_expr.object().ok()?;
156	    let (reference, object_name) = global_identifier(&object)?;
157	    let object_name_text = object_name.text();
158	
159	    if is_global_object(object_name_text) && model.binding(&reference).is_none() {
160	        let member_expr = computed_member_expr.member().ok()?;
161	        if let AnyJsExpression::AnyJsLiteralExpression(
162	            AnyJsLiteralExpression::JsStringLiteralExpression(string_literal),
163	        ) = member_expr
164	        {
165	            let string_token = string_literal.value_token().ok()?;
166	            let string_text = string_token.text_trimmed();
167	            let member_name = string_text.trim_matches('"').trim_matches('\'');
168	
169	            if is_forbidden_function(member_name) {
170	                Some(member_name.to_string())
171	            } else {
172	                None
173	            }
174	        } else {
175	            None
176	        }
177	    } else {
178	        None
179	    }
180	}
181	
182	fn is_forbidden_function(name: &str) -> bool {
183	    FORBIDDEN_FUNCTIONS.contains(&name)
184	}
185	
186	fn is_global_object(name: &str) -> bool {
187	    GLOBAL_OBJECTS.contains(&name)
188	}
