13	/// Generates the options struct for a new analyzer rule.
14	/// This function creates a new struct with the name `<RuleName>Options` and saves it in the
15	/// `biome_rule_options` crate.
16	pub fn generate_analyzer_rule_options(
17	    rule_name: &str,
18	    mode: Mode,
19	    register_mod: bool,
20	) -> Result<()> {
21	    let struct_name = Ident::new(
22	        &format!("{}Options", Case::Pascal.convert(rule_name)),
23	        Span::call_site(),
24	    );
25	
26	    let content = quote! {
27	        use biome_deserialize_macros::{Deserializable, Merge};
28	        use serde::{Deserialize, Serialize};
29	
30	        #[derive(Default, Clone, Debug, Deserialize, Deserializable, Merge, Eq, PartialEq, Serialize)]
31	        #[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
32	        #[serde(rename_all = "camelCase", deny_unknown_fields, default)]
33	        pub struct #struct_name {}
34	    };
35	
36	    let snake_rule_name = Case::Snake.convert(rule_name);
37	    let file_name = format!("{snake_rule_name}.rs");
38	    let file_path = get_analyzer_rule_options_path().join(file_name);
39	
40	    update(
41	        file_path.as_path(),
42	        &reformat_without_preamble(content)?,
43	        &mode,
44	    )?;
45	
46	    if register_mod {
47	        register_analyzer_rule_options(&snake_rule_name)?;
48	    }
49	
50	    Ok(())
51	}
