53	/// Registers the new analyzer rule options module in the `lib.rs` file of the `biome_rule_options` crate.
54	/// This is a temporal addition to let configuration codegen properly run afterward.
55	/// Configuration codegen will re-create the `lib.rs` file and put mods in the right order.
56	fn register_analyzer_rule_options(mod_name: &str) -> Result<()> {
57	    let lib_path = get_analyzer_rule_options_path().join("lib.rs");
58	    let current_lib_content = std::fs::read_to_string(&lib_path)?;
59	    let mod_declaration = format!("pub mod {mod_name};");
60	    if current_lib_content
61	        .lines()
62	        .any(|line| line.trim() == mod_declaration)
63	    {
64	        return Ok(());
65	    }
66	    std::fs::write(
67	        &lib_path,
68	        format!("{current_lib_content}{mod_declaration}\n"),
69	    )?;
70	    Ok(())
