const IMPLIED_EVAL_FUNCTIONS: &[&str] = &["setTimeout", "setInterval", "setImmediate"];

declare_lint_rule! {
    /// Disallow the use of `eval()`-like functions.
    ///
    /// Passing strings to `setTimeout`, `setInterval`, or `setImmediate` is a form of
    /// implied `eval()`. The string is compiled and executed as JavaScript, which exposes
    /// the code to the same security and performance issues as `eval()`.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// setTimeout("alert('Hello world');", 100);
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// setInterval("alert('Hello world');", 100);
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// window.setTimeout("count = 5", 10);
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// setTimeout(function() { alert("Hello world"); }, 100);
    /// ```
    ///
    /// ```js
    /// setInterval(() => { alert("Hello world"); }, 100);
    /// ```
    ///
    pub NoImpliedEval {
        version: "next",
        name: "noImpliedEval",
        language: "js",
        recommended: false,
        severity: Severity::Error,
    }
}

impl Rule for NoImpliedEval {
    type Query = Semantic<JsCallExpression>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = NoImpliedEvalOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let call = ctx.query();
        let model = ctx.model();

        // Ensure the callee resolves to a global `setTimeout`, `setInterval`, or
        // `setImmediate`, possibly accessed through `window` or `globalThis`.
        let callee = call.callee().ok()?;
        if !is_implied_eval_callee(&callee, model) {
